import * as SQLite from 'expo-sqlite';

export interface EmotionRecord {
  id?: number;
  timestamp: string;
  emotionScore: number;
  latitude: number | null;
  longitude: number | null;
  videoPath: string | null;
  address: string | null;
}

let db: SQLite.SQLiteDatabase | null = null;

export const initDatabase = async () => {
  try {
    db = await SQLite.openDatabaseAsync('emogo.db');

    await db.execAsync(`
      CREATE TABLE IF NOT EXISTS emotion_records (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp TEXT NOT NULL,
        emotionScore INTEGER NOT NULL,
        latitude REAL,
        longitude REAL,
        videoPath TEXT,
        address TEXT
      );
    `);

    console.log('Database initialized successfully');
  } catch (error) {
    console.error('Error initializing database:', error);
    throw error;
  }
};

export const insertEmotionRecord = async (record: Omit<EmotionRecord, 'id'>) => {
  if (!db) {
    await initDatabase();
  }

  try {
    const result = await db!.runAsync(
      `INSERT INTO emotion_records (timestamp, emotionScore, latitude, longitude, videoPath, address) 
       VALUES (?, ?, ?, ?, ?, ?)`,
      [
        record.timestamp,
        record.emotionScore,
        record.latitude,
        record.longitude,
        record.videoPath,
        record.address
      ]
    );

    console.log('Record inserted with id:', result.lastInsertRowId);
    return result.lastInsertRowId;
  } catch (error) {
    console.error('Error inserting record:', error);
    throw error;
  }
};

export const getAllEmotionRecords = async (): Promise<EmotionRecord[]> => {
  if (!db) {
    await initDatabase();
  }

  try {
    const records = await db!.getAllAsync<EmotionRecord>(
      'SELECT * FROM emotion_records ORDER BY timestamp DESC'
    );
    return records;
  } catch (error) {
    console.error('Error getting records:', error);
    throw error;
  }
};

export const getRecordCount = async (): Promise<number> => {
  if (!db) {
    await initDatabase();
  }

  try {
    const result = await db!.getFirstAsync<{ count: number }>(
      'SELECT COUNT(*) as count FROM emotion_records'
    );
    return result?.count || 0;
  } catch (error) {
    console.error('Error getting record count:', error);
    throw error;
  }
};

import * as Notifications from 'expo-notifications';
import { Platform } from 'react-native';

// 設定通知處理器
Notifications.setNotificationHandler({
  handleNotification: async () => ({
    shouldShowAlert: true,
    shouldPlaySound: true,
    shouldSetBadge: true,
    priority: Notifications.AndroidNotificationPriority.MAX,
  }),
});

export const requestNotificationPermissions = async () => {
  try {
    const { status: existingStatus } = await Notifications.getPermissionsAsync();
    let finalStatus = existingStatus;

    if (existingStatus !== 'granted') {
      const { status } = await Notifications.requestPermissionsAsync();
      finalStatus = status;
    }

    if (finalStatus !== 'granted') {
      alert('請允許通知權限以接收情緒記錄提醒！');
      return false;
    }

    // Android 13+ 需要額外的通知權限
    if (Platform.OS === 'android') {
      await Notifications.setNotificationChannelAsync('emotion-reminders', {
        name: 'Emotion Reminders',
        importance: Notifications.AndroidImportance.MAX,
        vibrationPattern: [0, 250, 250, 250],
        lightColor: '#FF231F7C',
        sound: 'default',
        enableVibrate: true,
        showBadge: true,
      });
    }

    return true;
  } catch (error) {
    console.error('Error requesting notification permissions:', error);
    return false;
  }
};

export const scheduleDailyNotifications = async () => {
  try {
    // 取消所有現有的通知
    await Notifications.cancelAllScheduledNotificationsAsync();

    const times = [
      { hour: 9, minute: 0, label: 'morning' },
      { hour: 12, minute: 0, label: 'afternoon' },
      { hour: 18, minute: 0, label: 'evening' },
    ];

    for (const time of times) {
      await Notifications.scheduleNotificationAsync({
        content: {
          title: '🌟 Time to check in!',
          body: 'How are you feeling right now? Take a moment to record your emotions.',
          sound: true,
          priority: Notifications.AndroidNotificationPriority.MAX,
          categoryIdentifier: 'emotion-reminder',
        },
        trigger: {
          hour: time.hour,
          minute: time.minute,
          repeats: true,
          channelId: 'emotion-reminders',
        },
      });

      console.log(`Scheduled ${time.label} notification at ${time.hour}:${time.minute}`);
    }

    console.log('All daily notifications scheduled successfully');
    return true;
  } catch (error) {
    console.error('Error scheduling notifications:', error);
    return false;
  }
};

export const sendTestNotification = async () => {
  try {
    await Notifications.scheduleNotificationAsync({
      content: {
        title: '🧪 Test Notification',
        body: 'This is a test notification. Your notifications are working!',
        sound: true,
        priority: Notifications.AndroidNotificationPriority.MAX,
      },
      trigger: {
        seconds: 2,
        channelId: 'emotion-reminders',
      },
    });
  } catch (error) {
    console.error('Error sending test notification:', error);
  }
};

export const getScheduledNotifications = async () => {
  try {
    const scheduled = await Notifications.getAllScheduledNotificationsAsync();
    console.log('Scheduled notifications:', scheduled);
    return scheduled;
  } catch (error) {
    console.error('Error getting scheduled notifications:', error);
    return [];
  }
};

import * as Location from 'expo-location';

export interface LocationData {
  latitude: number;
  longitude: number;
  address: string | null;
}

export const requestLocationPermissions = async () => {
  try {
    const { status: foregroundStatus } = await Location.requestForegroundPermissionsAsync();

    if (foregroundStatus !== 'granted') {
      alert('請允許位置權限以追蹤您的情緒模式！');
      return false;
    }

    // 嘗試請求背景位置權限（iOS 需要）
    const { status: backgroundStatus } = await Location.requestBackgroundPermissionsAsync();

    if (backgroundStatus !== 'granted') {
      console.log('Background location permission not granted, but foreground is OK');
    }

    return true;
  } catch (error) {
    console.error('Error requesting location permissions:', error);
    return false;
  }
};

export const getCurrentLocation = async (): Promise<LocationData | null> => {
  try {
    const location = await Location.getCurrentPositionAsync({
      accuracy: Location.Accuracy.Balanced,
    });

    const { latitude, longitude } = location.coords;

    // 反向地理編碼獲取地址
    let address: string | null = null;
    try {
      const [geocode] = await Location.reverseGeocodeAsync({
        latitude,
        longitude,
      });

      if (geocode) {
        address = `${geocode.city || ''}, ${geocode.region || ''}, ${geocode.country || ''}`.trim();
      }
    } catch (geocodeError) {
      console.warn('Could not get address:', geocodeError);
    }

    return { latitude, longitude, address };
  } catch (error) {
    console.error('Error getting location:', error);
    return null;
  }
};

export const startLocationTracking = async () => {
  try {
    await Location.startLocationUpdatesAsync('emotion-location-tracking', {
      accuracy: Location.Accuracy.Balanced,
      timeInterval: 60000, // 每分鐘更新一次
      distanceInterval: 100, // 或移動100米更新
    });
    console.log('Location tracking started');
  } catch (error) {
    console.error('Error starting location tracking:', error);
  }
};

import * as FileSystem from 'expo-file-system';
import * as Sharing from 'expo-sharing';
import { getAllEmotionRecords } from './database';

export const exportDataToJSON = async () => {
  try {
    const records = await getAllEmotionRecords();

    if (records.length === 0) {
      alert('No data to export!');
      return null;
    }

    const jsonData = JSON.stringify(records, null, 2);
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const fileName = `emogo_data_${timestamp}.json`;
    const filePath = `${FileSystem.documentDirectory}${fileName}`;

    await FileSystem.writeAsStringAsync(filePath, jsonData);

    console.log('Data exported to:', filePath);
    return filePath;
  } catch (error) {
    console.error('Error exporting data:', error);
    throw error;
  }
};

export const shareExportedData = async (filePath: string) => {
  try {
    const isAvailable = await Sharing.isAvailableAsync();

    if (!isAvailable) {
      alert('Sharing is not available on this device');
      return false;
    }

    await Sharing.shareAsync(filePath, {
      mimeType: 'application/json',
      dialogTitle: 'Export EmoGo Data',
      UTI: 'public.json',
    });

    return true;
  } catch (error) {
    console.error('Error sharing data:', error);
    return false;
  }
};

export const exportAndShareData = async () => {
  try {
    const filePath = await exportDataToJSON();
    if (filePath) {
      await shareExportedData(filePath);
      return true;
    }
    return false;
  } catch (error) {
    console.error('Error in export and share:', error);
    alert('Failed to export data: ' + (error as Error).message);
    return false;
  }
};

export const createDataFolder = async () => {
  try {
    const dataFolderPath = `${FileSystem.documentDirectory}data/`;
    const folderInfo = await FileSystem.getInfoAsync(dataFolderPath);

    if (!folderInfo.exists) {
      await FileSystem.makeDirectoryAsync(dataFolderPath, { intermediates: true });
      console.log('Data folder created at:', dataFolderPath);
    }

    return dataFolderPath;
  } catch (error) {
    console.error('Error creating data folder:', error);
    throw error;
  }
};

export const saveDataToFolder = async () => {
  try {
    const records = await getAllEmotionRecords();

    if (records.length === 0) {
      alert('No data to save!');
      return null;
    }

    const dataFolderPath = await createDataFolder();
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const fileName = `emogo_export_${timestamp}.json`;
    const filePath = `${dataFolderPath}${fileName}`;

    const jsonData = JSON.stringify(records, null, 2);
    await FileSystem.writeAsStringAsync(filePath, jsonData);

    console.log('Data saved to folder:', filePath);
    return filePath;
  } catch (error) {
    console.error('Error saving data to folder:', error);
    throw error;
  }
};

import React, { useState, useRef } from 'react';
import { View, Text, TouchableOpacity, StyleSheet, Alert } from 'react-native';
import { CameraView, CameraType, useCameraPermissions } from 'expo-camera';
import * as MediaLibrary from 'expo-media-library';
import * as FileSystem from 'expo-file-system';

interface VideoRecorderProps {
  onVideoRecorded: (videoUri: string) => void;
  onCancel: () => void;
}

export default function VideoRecorder({ onVideoRecorded, onCancel }: VideoRecorderProps) {
  const [facing, setFacing] = useState<CameraType>('front');
  const [isRecording, setIsRecording] = useState(false);
  const [countdown, setCountdown] = useState<number | null>(null);
  const [permission, requestPermission] = useCameraPermissions();
  const [mediaPermission, requestMediaPermission] = MediaLibrary.usePermissions();
  const cameraRef = useRef<CameraView>(null);

  if (!permission || !mediaPermission) {
    return <View style={styles.container}><Text>Loading...</Text></View>;
  }

  if (!permission.granted || !mediaPermission.granted) {
    return (
      <View style={styles.container}>
        <Text style={styles.message}>需要相機和媒體庫權限</Text>
        <TouchableOpacity style={styles.button} onPress={() => {
          requestPermission();
          requestMediaPermission();
        }}>
          <Text style={styles.buttonText}>授予權限</Text>
        </TouchableOpacity>
      </View>
    );
  }

  const startRecording = async () => {
    if (!cameraRef.current || isRecording) return;

    try {
      // 倒數計時 3, 2, 1
      for (let i = 3; i > 0; i--) {
        setCountdown(i);
        await new Promise(resolve => setTimeout(resolve, 1000));
      }
      setCountdown(null);

      setIsRecording(true);

      const video = await cameraRef.current.recordAsync({
        maxDuration: 1, // 1 秒
        quality: '720p',
      });

      setIsRecording(false);

      if (video?.uri) {
        await saveVideo(video.uri);
      }
    } catch (error) {
      console.error('Error recording video:', error);
      setIsRecording(false);
      setCountdown(null);
      Alert.alert('Error', 'Failed to record video');
    }
  };

  const saveVideo = async (uri: string) => {
    try {
      // 保存到媒體庫
      const asset = await MediaLibrary.createAssetAsync(uri);
      console.log('Video saved to media library:', asset.uri);

      // 複製到 app 的文件目錄
      const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
      const fileName = `emogo_video_${timestamp}.mp4`;
      const newPath = `${FileSystem.documentDirectory}${fileName}`;

      await FileSystem.copyAsync({
        from: uri,
        to: newPath,
      });

      console.log('Video copied to:', newPath);
      onVideoRecorded(newPath);
    } catch (error) {
      console.error('Error saving video:', error);
      Alert.alert('Error', 'Failed to save video');
    }
  };

  const stopRecording = () => {
    if (cameraRef.current && isRecording) {
      cameraRef.current.stopRecording();
    }
  };

  return (
    <View style={styles.container}>
      <CameraView 
        ref={cameraRef} 
        style={styles.camera} 
        facing={facing}
        mode="video"
      >
        <View style={styles.overlay}>
          {countdown && (
            <View style={styles.countdownContainer}>
              <Text style={styles.countdownText}>{countdown}</Text>
            </View>
          )}

          {isRecording && (
            <View style={styles.recordingIndicator}>
              <View style={styles.recordingDot} />
              <Text style={styles.recordingText}>錄製中...</Text>
            </View>
          )}

          <View style={styles.buttonContainer}>
            <TouchableOpacity 
              style={[styles.button, styles.cancelButton]} 
              onPress={onCancel}
              disabled={isRecording}
            >
              <Text style={styles.buttonText}>取消</Text>
            </TouchableOpacity>

            <TouchableOpacity
              style={[styles.recordButton, isRecording && styles.recordingButton]}
              onPress={isRecording ? stopRecording : startRecording}
              disabled={countdown !== null}
            >
              <View style={styles.recordButtonInner} />
            </TouchableOpacity>

            <TouchableOpacity
              style={[styles.button, styles.flipButton]}
              onPress={() => setFacing(current => (current === 'back' ? 'front' : 'back'))}
              disabled={isRecording || countdown !== null}
            >
              <Text style={styles.buttonText}>翻轉</Text>
            </TouchableOpacity>
          </View>
        </View>
      </CameraView>
    </View>
  );
}

