import React, { useState } from 'react';
import { View, Text, StyleSheet, Dimensions } from 'react-native';
import Slider from '@react-native-community/slider';

interface EmotionSliderProps {
  value: number;
  onValueChange: (value: number) => void;
}

const SCREEN_WIDTH = Dimensions.get('window').width;

export default function EmotionSlider({ value, onValueChange }: EmotionSliderProps) {
  const getEmotionLabel = (score: number): string => {
    if (score === 0) return 'Awfully Bad 😢';
    if (score <= 2) return 'Very Bad 😞';
    if (score <= 4) return 'Bad 😔';
    if (score <= 5) return 'Neutral 😐';
    if (score <= 7) return 'Good 🙂';
    if (score <= 9) return 'Very Good 😊';
    return 'Perfectly Good 😄';
  };

  const getEmotionColor = (score: number): string => {
    // 從紅色 (0) 到黃色 (5) 到綠色 (10)
    if (score <= 5) {
      // 紅色到黃色
      const ratio = score / 5;
      const red = 255;
      const green = Math.round(165 + (90 * ratio)); // 165 -> 255
      return `rgb(${red}, ${green}, 0)`;
    } else {
      // 黃色到綠色
      const ratio = (score - 5) / 5;
      const red = Math.round(255 * (1 - ratio)); // 255 -> 0
      const green = 255;
      return `rgb(${red}, ${green}, 0)`;
    }
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>How are you feeling right now?</Text>

      <View style={styles.scoreContainer}>
        <Text style={[styles.scoreText, { color: getEmotionColor(value) }]}>
          {value}
        </Text>
        <Text style={[styles.labelText, { color: getEmotionColor(value) }]}>
          {getEmotionLabel(value)}
        </Text>
      </View>

      <View style={styles.sliderContainer}>
        <View style={styles.gradientBackground}>
          {/* 漸層背景模擬 */}
          {[...Array(11)].map((_, i) => (
            <View
              key={i}
              style={[
                styles.gradientSegment,
                { backgroundColor: getEmotionColor(i) }
              ]}
            />
          ))}
        </View>

        <Slider
          style={styles.slider}
          minimumValue={0}
          maximumValue={10}
          step={1}
          value={value}
          onValueChange={onValueChange}
          minimumTrackTintColor="transparent"
          maximumTrackTintColor="transparent"
          thumbTintColor="#ffffff"
        />
      </View>

      <View style={styles.labelsContainer}>
        <View style={styles.labelItem}>
          <Text style={[styles.extremeLabel, { color: '#ff4444' }]}>0</Text>
          <Text style={styles.extremeDescription}>Awfully Bad</Text>
        </View>
        <View style={[styles.labelItem, { alignItems: 'flex-end' }]}>
          <Text style={[styles.extremeLabel, { color: '#00ff00' }]}>10</Text>
          <Text style={styles.extremeDescription}>Perfectly Good</Text>
        </View>
      </View>
    </View>
  );
}

