import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  ScrollView,
  Alert,
  ActivityIndicator,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import EmotionSlider from '@/components/EmotionSlider';
import VideoRecorder from '@/components/VideoRecorder';
import { insertEmotionRecord, getRecordCount } from '@/utils/database';
import { getCurrentLocation } from '@/utils/location';

export default function RecordScreen() {
  const [emotionScore, setEmotionScore] = useState(5);
  const [showCamera, setShowCamera] = useState(false);
  const [videoPath, setVideoPath] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [recordCount, setRecordCount] = useState(0);

  useEffect(() => {
    loadRecordCount();
  }, []);

  const loadRecordCount = async () => {
    try {
      const count = await getRecordCount();
      setRecordCount(count);
    } catch (error) {
      console.error('Error loading record count:', error);
    }
  };

  const handleVideoRecorded = (uri: string) => {
    setVideoPath(uri);
    setShowCamera(false);
    Alert.alert('Success', 'Video recorded successfully! 🎥');
  };

  const handleSubmit = async () => {
    if (!videoPath) {
      Alert.alert('Missing Video', 'Please record a video selfie first!');
      return;
    }

    setIsLoading(true);

    try {
      // 獲取位置
      const location = await getCurrentLocation();

      // 保存記錄
      const record = {
        timestamp: new Date().toISOString(),
        emotionScore,
        latitude: location?.latitude || null,
        longitude: location?.longitude || null,
        videoPath,
        address: location?.address || null,
      };

      await insertEmotionRecord(record);

      Alert.alert(
        'Success! 🎉',
        'Your emotion record has been saved successfully.',
        [
          {
            text: 'OK',
            onPress: () => {
              // 重置表單
              setEmotionScore(5);
              setVideoPath(null);
              loadRecordCount();
            },
          },
        ]
      );
    } catch (error) {
      console.error('Error submitting record:', error);
      Alert.alert('Error', 'Failed to save record. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  if (showCamera) {
    return (
      <VideoRecorder
        onVideoRecorded={handleVideoRecorded}
        onCancel={() => setShowCamera(false)}
      />
    );
  }

  return (
    <SafeAreaView style={styles.container}>
      <ScrollView contentContainerStyle={styles.scrollContent}>
        <View style={styles.header}>
          <Text style={styles.headerTitle}>EmoGo</Text>
          <Text style={styles.headerSubtitle}>Track your emotional journey</Text>
          <View style={styles.badge}>
            <Text style={styles.badgeText}>📊 {recordCount} records</Text>
          </View>
        </View>

        <EmotionSlider value={emotionScore} onValueChange={setEmotionScore} />

        <View style={styles.videoSection}>
          <Text style={styles.sectionTitle}>Video Selfie (1 second)</Text>
          {videoPath ? (
            <View style={styles.videoStatus}>
              <Text style={styles.videoStatusText}>✅ Video recorded!</Text>
              <TouchableOpacity
                style={styles.rerecordButton}
                onPress={() => setShowCamera(true)}
              >
                <Text style={styles.rerecordButtonText}>Re-record</Text>
              </TouchableOpacity>
            </View>
          ) : (
            <TouchableOpacity
              style={styles.recordVideoButton}
              onPress={() => setShowCamera(true)}
            >
              <Text style={styles.recordVideoButtonText}>📹 Record Video</Text>
            </TouchableOpacity>
          )}
        </View>

        <TouchableOpacity
          style={[styles.submitButton, isLoading && styles.submitButtonDisabled]}
          onPress={handleSubmit}
          disabled={isLoading || !videoPath}
        >
          {isLoading ? (
            <ActivityIndicator color="#fff" />
          ) : (
            <Text style={styles.submitButtonText}>
              Submit Record 🚀
            </Text>
          )}
        </TouchableOpacity>

        <View style={styles.infoBox}>
          <Text style={styles.infoTitle}>📍 Location Tracking</Text>
          <Text style={styles.infoText}>
            Your location will be automatically recorded when you submit.
          </Text>
        </View>
      </ScrollView>
    </SafeAreaView>
  );
}

