import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  FlatList,
  Alert,
  ActivityIndicator,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { getAllEmotionRecords, EmotionRecord } from '@/utils/database';
import { exportAndShareData } from '@/utils/dataExport';

export default function DataScreen() {
  const [records, setRecords] = useState<EmotionRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isExporting, setIsExporting] = useState(false);

  useEffect(() => {
    loadRecords();
  }, []);

  const loadRecords = async () => {
    setIsLoading(true);
    try {
      const data = await getAllEmotionRecords();
      setRecords(data);
    } catch (error) {
      console.error('Error loading records:', error);
      Alert.alert('Error', 'Failed to load records');
    } finally {
      setIsLoading(false);
    }
  };

  const handleExport = async () => {
    setIsExporting(true);
    try {
      const success = await exportAndShareData();
      if (success) {
        Alert.alert('Success', 'Data exported successfully! 📁');
      }
    } catch (error) {
      console.error('Error exporting data:', error);
      Alert.alert('Error', 'Failed to export data');
    } finally {
      setIsExporting(false);
    }
  };

  const formatDate = (timestamp: string) => {
    const date = new Date(timestamp);
    return date.toLocaleString('en-US', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const getEmotionEmoji = (score: number) => {
    if (score <= 2) return '😢';
    if (score <= 4) return '😔';
    if (score <= 5) return '😐';
    if (score <= 7) return '🙂';
    if (score <= 9) return '😊';
    return '😄';
  };

  const getScoreColor = (score: number) => {
    if (score <= 3) return '#ff4444';
    if (score <= 5) return '#ff9800';
    if (score <= 7) return '#ffd700';
    return '#4caf50';
  };

  const renderRecord = ({ item }: { item: EmotionRecord }) => (
    <View style={styles.recordCard}>
      <View style={styles.recordHeader}>
        <Text style={styles.recordDate}>{formatDate(item.timestamp)}</Text>
        <View style={[styles.scoreBadge, { backgroundColor: getScoreColor(item.emotionScore) }]}>
          <Text style={styles.scoreText}>
            {getEmotionEmoji(item.emotionScore)} {item.emotionScore}
          </Text>
        </View>
      </View>
      {item.address && (
        <Text style={styles.locationText}>📍 {item.address}</Text>
      )}
      {item.videoPath && (
        <Text style={styles.videoText}>🎥 Video recorded</Text>
      )}
    </View>
  );

  if (isLoading) {
    return (
      <SafeAreaView style={styles.container}>
        <View style={styles.loadingContainer}>
          <ActivityIndicator size="large" color="#007AFF" />
          <Text style={styles.loadingText}>Loading records...</Text>
        </View>
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView style={styles.container}>
      <View style={styles.header}>
        <Text style={styles.headerTitle}>Your Records</Text>
        <Text style={styles.headerSubtitle}>
          Total: {records.length} {records.length === 1 ? 'record' : 'records'}
        </Text>
      </View>

      {records.length === 0 ? (
        <View style={styles.emptyContainer}>
          <Text style={styles.emptyEmoji}>📝</Text>
          <Text style={styles.emptyText}>No records yet</Text>
          <Text style={styles.emptySubtext}>
            Start tracking your emotions to see your data here!
          </Text>
        </View>
      ) : (
        <>
          <FlatList
            data={records}
            renderItem={renderRecord}
            keyExtractor={(item) => item.id?.toString() || Math.random().toString()}
            contentContainerStyle={styles.listContent}
            refreshing={isLoading}
            onRefresh={loadRecords}
          />

          <TouchableOpacity
            style={[styles.exportButton, isExporting && styles.exportButtonDisabled]}
            onPress={handleExport}
            disabled={isExporting}
          >
            {isExporting ? (
              <ActivityIndicator color="#fff" />
            ) : (
              <>
                <Text style={styles.exportButtonText}>📤 Export Data</Text>
                <Text style={styles.exportButtonSubtext}>
                  Share as JSON file
                </Text>
              </>
            )}
          </TouchableOpacity>
        </>
      )}
    </SafeAreaView>
  );
}

