import { useEffect, useRef } from 'react';
import { AppState } from 'react-native';
import * as Notifications from 'expo-notifications';
import { initDatabase } from '@/utils/database';
import {
  requestNotificationPermissions,
  scheduleDailyNotifications,
} from '@/utils/notifications';
import { requestLocationPermissions } from '@/utils/location';

export function useAppInitialization() {
  const appState = useRef(AppState.currentState);

  useEffect(() => {
    initializeApp();

    // 監聽通知
    const notificationListener = Notifications.addNotificationReceivedListener(
      (notification) => {
        console.log('Notification received:', notification);
      }
    );

    const responseListener = Notifications.addNotificationResponseReceivedListener(
      (response) => {
        console.log('Notification response:', response);
        // TODO: 導航到記錄頁面
      }
    );

    // 監聽 App 狀態
    const subscription = AppState.addEventListener('change', (nextAppState) => {
      if (
        appState.current.match(/inactive|background/) &&
        nextAppState === 'active'
      ) {
        console.log('App has come to the foreground');
      }
      appState.current = nextAppState;
    });

    return () => {
      notificationListener.remove();
      responseListener.remove();
      subscription.remove();
    };
  }, []);

  const initializeApp = async () => {
    try {
      console.log('Initializing app...');

      // 初始化資料庫
      await initDatabase();
      console.log('✅ Database initialized');

      // 請求通知權限
      const notificationGranted = await requestNotificationPermissions();
      if (notificationGranted) {
        await scheduleDailyNotifications();
        console.log('✅ Notifications scheduled');
      }

      // 請求位置權限
      const locationGranted = await requestLocationPermissions();
      if (locationGranted) {
        console.log('✅ Location permissions granted');
      }

      console.log('🎉 App initialization complete');
    } catch (error) {
      console.error('❌ Error initializing app:', error);
    }
  };
}

import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  ScrollView,
  Alert,
  Switch,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import * as Notifications from 'expo-notifications';
import {
  requestNotificationPermissions,
  scheduleDailyNotifications,
  sendTestNotification,
  getScheduledNotifications,
} from '@/utils/notifications';
import { requestLocationPermissions } from '@/utils/location';
import { getRecordCount } from '@/utils/database';

export default function SettingsScreen() {
  const [notificationsEnabled, setNotificationsEnabled] = useState(false);
  const [recordCount, setRecordCount] = useState(0);

  useEffect(() => {
    checkPermissions();
    loadStats();
  }, []);

  const checkPermissions = async () => {
    const { status } = await Notifications.getPermissionsAsync();
    setNotificationsEnabled(status === 'granted');
  };

  const loadStats = async () => {
    const count = await getRecordCount();
    setRecordCount(count);
  };

  const handleToggleNotifications = async (value: boolean) => {
    if (value) {
      const granted = await requestNotificationPermissions();
      if (granted) {
        await scheduleDailyNotifications();
        setNotificationsEnabled(true);
        Alert.alert(
          'Notifications Enabled',
          'You will receive reminders at 9 AM, 12 PM, and 6 PM daily.'
        );
      }
    } else {
      await Notifications.cancelAllScheduledNotificationsAsync();
      setNotificationsEnabled(false);
      Alert.alert('Notifications Disabled', 'All scheduled notifications have been cancelled.');
    }
  };

  const handleTestNotification = async () => {
    await sendTestNotification();
    Alert.alert('Test Sent', 'You should receive a test notification in 2 seconds!');
  };

  const handleCheckScheduled = async () => {
    const scheduled = await getScheduledNotifications();
    Alert.alert(
      'Scheduled Notifications',
      `You have ${scheduled.length} scheduled notification(s).\n\nCheck the console for details.`
    );
  };

  const handleRequestLocationPermission = async () => {
    const granted = await requestLocationPermissions();
    if (granted) {
      Alert.alert('Success', 'Location permissions granted! 📍');
    } else {
      Alert.alert('Error', 'Location permissions denied.');
    }
  };

  return (
    <SafeAreaView style={styles.container}>
      <ScrollView contentContainerStyle={styles.scrollContent}>
        <View style={styles.header}>
          <Text style={styles.headerTitle}>Settings</Text>
          <Text style={styles.headerSubtitle}>Manage your EmoGo experience</Text>
        </View>

        {/* Stats Section */}
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>📊 Statistics</Text>
          <View style={styles.statCard}>
            <Text style={styles.statNumber}>{recordCount}</Text>
            <Text style={styles.statLabel}>Total Records</Text>
          </View>
          <View style={styles.goalCard}>
            <Text style={styles.goalText}>
              {recordCount >= 4
                ? '🎉 Goal Achieved! You have 4+ records!'
                : `📝 ${4 - recordCount} more record(s) needed to reach your goal`}
            </Text>
          </View>
        </View>

        {/* Notifications Section */}
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>🔔 Notifications</Text>

          <View style={styles.settingRow}>
            <View style={styles.settingInfo}>
              <Text style={styles.settingLabel}>Daily Reminders</Text>
              <Text style={styles.settingDescription}>
                9:00 AM, 12:00 PM, 6:00 PM
              </Text>
            </View>
            <Switch
              value={notificationsEnabled}
              onValueChange={handleToggleNotifications}
              trackColor={{ false: '#767577', true: '#81b0ff' }}
              thumbColor={notificationsEnabled ? '#007AFF' : '#f4f3f4'}
            />
          </View>

          <TouchableOpacity style={styles.button} onPress={handleTestNotification}>
            <Text style={styles.buttonText}>Send Test Notification</Text>
          </TouchableOpacity>

          <TouchableOpacity
            style={[styles.button, styles.secondaryButton]}
            onPress={handleCheckScheduled}
          >
            <Text style={[styles.buttonText, styles.secondaryButtonText]}>
              Check Scheduled Notifications
            </Text>
          </TouchableOpacity>
        </View>

        {/* Permissions Section */}
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>🔐 Permissions</Text>

          <TouchableOpacity
            style={styles.permissionButton}
            onPress={handleRequestLocationPermission}
          >
            <Text style={styles.permissionIcon}>📍</Text>
            <View style={styles.permissionInfo}>
              <Text style={styles.permissionTitle}>Location Access</Text>
              <Text style={styles.permissionDescription}>
                Required for tracking emotional patterns
              </Text>
            </View>
          </TouchableOpacity>
        </View>

        {/* Info Section */}
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>ℹ️ Information</Text>
          <View style={styles.infoCard}>
            <Text style={styles.infoText}>
              <Text style={styles.infoBold}>App Version:</Text> 1.0.0
            </Text>
            <Text style={styles.infoText}>
              <Text style={styles.infoBold}>Purpose:</Text> Track emotional patterns with location and video data
            </Text>
            <Text style={styles.infoText}>
              <Text style={styles.infoBold}>Goal:</Text> Record at least 4 emotion entries
            </Text>
          </View>
        </View>

        {/* Instructions */}
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>📖 How to Use</Text>
          <View style={styles.instructionCard}>
            <Text style={styles.instructionStep}>1️⃣ Enable notifications to receive daily reminders</Text>
            <Text style={styles.instructionStep}>2️⃣ When notified, rate your emotion (0-10)</Text>
            <Text style={styles.instructionStep}>3️⃣ Record a 1-second video selfie</Text>
            <Text style={styles.instructionStep}>4️⃣ Submit to save with automatic location</Text>
            <Text style={styles.instructionStep}>5️⃣ Export data after 4+ records</Text>
          </View>
        </View>
      </ScrollView>
    </SafeAreaView>
  );
}

