  scheduleDailyNotifications,
  sendTestNotification,
  getScheduledNotifications,
} from '@/utils/notifications';
import { requestLocationPermissions } from '@/utils/location';
import { getRecordCount } from '@/utils/database';

export default function SettingsScreen() {
  const [notificationsEnabled, setNotificationsEnabled] = useState(false);
  const [recordCount, setRecordCount] = useState(0);

  useEffect(() => {
    checkPermissions();
    loadStats();
  }, []);

  const checkPermissions = async () => {
    const { status } = await Notifications.getPermissionsAsync();
    setNotificationsEnabled(status === 'granted');
  };

  const loadStats = async () => {
    const count = await getRecordCount();
    setRecordCount(count);
  };

  const handleToggleNotifications = async (value: boolean) => {
    if (value) {
      const granted = await requestNotificationPermissions();
      if (granted) {
        await scheduleDailyNotifications();
        setNotificationsEnabled(true);
        Alert.alert(
          'Notifications Enabled',
          'You will receive reminders at 9 AM, 12 PM, and 6 PM daily.'
        );
      }
    } else {
      await Notifications.cancelAllScheduledNotificationsAsync();
      setNotificationsEnabled(false);
      Alert.alert('Notifications Disabled', 'All scheduled notifications have been cancelled.');
    }
  };

  const handleTestNotification = async () => {
    await sendTestNotification();
    Alert.alert('Test Sent', 'You should receive a test notification in 2 seconds!');
  };

  const handleCheckScheduled = async () => {
    const scheduled = await getScheduledNotifications();
    Alert.alert(
      'Scheduled Notifications',
      `You have ${scheduled.length} scheduled notification(s).\n\nCheck the console for details.`
    );
  };

  const handleRequestLocationPermission = async () => {
    const granted = await requestLocationPermissions();
