                ? '🎉 Goal Achieved! You have 4+ records!'
                : `📝 ${4 - recordCount} more record(s) needed to reach your goal`}
            </Text>
          </View>
        </View>

        {/* Notifications Section */}
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>🔔 Notifications</Text>

          <View style={styles.settingRow}>
            <View style={styles.settingInfo}>
              <Text style={styles.settingLabel}>Daily Reminders</Text>
              <Text style={styles.settingDescription}>
                9:00 AM, 12:00 PM, 6:00 PM
              </Text>
            </View>
            <Switch
              value={notificationsEnabled}
              onValueChange={handleToggleNotifications}
              trackColor={{ false: '#767577', true: '#81b0ff' }}
              thumbColor={notificationsEnabled ? '#007AFF' : '#f4f3f4'}
            />
          </View>

          <TouchableOpacity style={styles.button} onPress={handleTestNotification}>
            <Text style={styles.buttonText}>Send Test Notification</Text>
          </TouchableOpacity>

          <TouchableOpacity
            style={[styles.button, styles.secondaryButton]}
            onPress={handleCheckScheduled}
          >
            <Text style={[styles.buttonText, styles.secondaryButtonText]}>
              Check Scheduled Notifications
            </Text>
          </TouchableOpacity>
        </View>

        {/* Permissions Section */}
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>🔐 Permissions</Text>

          <TouchableOpacity
            style={styles.permissionButton}
            onPress={handleRequestLocationPermission}
          >
            <Text style={styles.permissionIcon}>📍</Text>
            <View style={styles.permissionInfo}>
              <Text style={styles.permissionTitle}>Location Access</Text>
              <Text style={styles.permissionDescription}>
                Required for tracking emotional patterns
              </Text>
            </View>
          </TouchableOpacity>
        </View>

        {/* Info Section */}
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>ℹ️ Information</Text>
          <View style={styles.infoCard}>
            <Text style={styles.infoText}>
              <Text style={styles.infoBold}>App Version:</Text> 1.0.0
            </Text>
            <Text style={styles.infoText}>
              <Text style={styles.infoBold}>Purpose:</Text> Track emotional patterns with location and video data
            </Text>
            <Text style={styles.infoText}>
              <Text style={styles.infoBold}>Goal:</Text> Record at least 4 emotion entries
            </Text>
          </View>
        </View>

        {/* Instructions */}
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>📖 How to Use</Text>
          <View style={styles.instructionCard}>
            <Text style={styles.instructionStep}>1️⃣ Enable notifications to receive daily reminders</Text>
            <Text style={styles.instructionStep}>2️⃣ When notified, rate your emotion (0-10)</Text>
            <Text style={styles.instructionStep}>3️⃣ Record a 1-second video selfie</Text>
            <Text style={styles.instructionStep}>4️⃣ Submit to save with automatic location</Text>
            <Text style={styles.instructionStep}>5️⃣ Export data after 4+ records</Text>
          </View>
        </View>
      </ScrollView>
    </SafeAreaView>
  );
}

