const handleSubmit = async () => {
  if (!videoPath) {
    Alert.alert('Missing Video', 'Please record a video selfie first!');
    return;
  }

  setIsLoading(true);

  try {
    // 獲取位置
    console.log('Getting location...');
    const location = await getCurrentLocation();
    console.log('Location:', location);

    // 保存記錄
    const record = {
      timestamp: new Date().toISOString(),
      emotionScore,
      latitude: location?.latitude || null,
      longitude: location?.longitude || null,
      videoPath,
      address: location?.address || null,
    };

    console.log('Inserting record:', record);
    const recordId = await insertEmotionRecord(record);
    console.log('Record inserted with ID:', recordId);

    Alert.alert(
      'Success! 🎉',
      'Your emotion record has been saved successfully.',
      [
        {
          text: 'OK',
          onPress: () => {
            // 重置表單
            setEmotionScore(5);
            setVideoPath(null);
            loadRecordCount();
          },
        },
      ]
    );
  } catch (error) {
    console.error('Error submitting record:', error);
    Alert.alert('Error', 'Failed to save record: ' + (error as Error).message);
  } finally {
    setIsLoading(false);
  }
};

useEffect(() => {
  loadRecords();

  // 監聽 focus 事件，每次進入頁面都重新載入
  const unsubscribe = navigation?.addListener?.('focus', () => {
    loadRecords();
  });

  return unsubscribe;
}, []);

const loadRecords = async () => {
  setIsLoading(true);
  try {
    console.log('Loading records...');
    const data = await getAllEmotionRecords();
    console.log('Records loaded:', data.length, 'records');
    setRecords(data);
  } catch (error) {
    console.error('Error loading records:', error);
    Alert.alert('Error', 'Failed to load records: ' + (error as Error).message);
  } finally {
    setIsLoading(false);
  }
};

import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  FlatList,
  Alert,
  ActivityIndicator,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useFocusEffect } from '@react-navigation/native';
import { getAllEmotionRecords, EmotionRecord } from '@/utils/database';
import { exportAndShareData } from '@/utils/dataExport';

useFocusEffect(
  React.useCallback(() => {
    checkPermissions();
    loadStats();
  }, [])
);

const checkPermissions = async () => {
  const { status } = await Notifications.getPermissionsAsync();
  setNotificationsEnabled(status === 'granted');
};

const loadStats = async () => {
  console.log('Loading stats...');
  const count = await getRecordCount();
  console.log('Record count:', count);
  setRecordCount(count);
};

import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  ScrollView,
  Alert,
  Switch,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useFocusEffect } from '@react-navigation/native';
import * as Notifications from 'expo-notifications';

export const initDatabase = async () => {
  try {
    if (db) {
      console.log('Database already initialized');
      return;
    }

    console.log('Opening database...');
    db = await SQLite.openDatabaseAsync('emogo.db');

    console.log('Creating table...');
    await db.execAsync(`
      CREATE TABLE IF NOT EXISTS emotion_records (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp TEXT NOT NULL,
        emotionScore INTEGER NOT NULL,
        latitude REAL,
        longitude REAL,
        videoPath TEXT,
        address TEXT
      );
    `);

    console.log('✅ Database initialized successfully');

    // 測試查詢以確認表存在
    const testQuery = await db.getAllAsync('SELECT * FROM emotion_records LIMIT 1');
    console.log('Test query result:', testQuery);
  } catch (error) {
    console.error('❌ Error initializing database:', error);
    throw error;
  }
};

