const getEmotionColor = (score: number): string => {
  // 從純紅色 (0) 到黃色 (5) 到綠色 (10)
  if (score <= 5) {
    // 純紅色到黃色
    const ratio = score / 5;
    const red = 255;
    const green = Math.round(255 * ratio); // 0 -> 255
    return `rgb(${red}, ${green}, 0)`;
  } else {
    // 黃色到綠色
    const ratio = (score - 5) / 5;
    const red = Math.round(255 * (1 - ratio)); // 255 -> 0
    const green = 255;
    return `rgb(${red}, ${green}, 0)`;
  }
};

