return (
  <SafeAreaView style={styles.container}>
    <ScrollView 
      contentContainerStyle={styles.scrollContent}
      showsVerticalScrollIndicator={false}
    >
      {/* Header - Apple style minimalist */}
      <View style={styles.header}>
        <Text style={styles.headerTitle}>How are you feeling?</Text>
        <Text style={styles.headerSubtitle}>
          {recordCount} {recordCount === 1 ? 'entry' : 'entries'} recorded
        </Text>
      </View>

      {/* Emotion Slider */}
      <View style={styles.sliderSection}>
        <EmotionSlider value={emotionScore} onValueChange={setEmotionScore} />
      </View>

      {/* Video Section - Clean and minimal */}
      <View style={styles.videoSection}>
        {videoPath ? (
          <View style={styles.videoCompleted}>
            <View style={styles.checkmarkCircle}>
              <Text style={styles.checkmark}>✓</Text>
            </View>
            <Text style={styles.videoCompletedText}>Video captured</Text>
            <TouchableOpacity onPress={() => setShowCamera(true)}>
              <Text style={styles.retakeLink}>Retake</Text>
            </TouchableOpacity>
          </View>
        ) : (
          <TouchableOpacity
            style={styles.videoButton}
            onPress={() => setShowCamera(true)}
            activeOpacity={0.8}
          >
            <View style={styles.cameraIcon}>
              <Text style={styles.cameraIconText}>📹</Text>
            </View>
            <Text style={styles.videoButtonText}>Capture video selfie</Text>
            <Text style={styles.videoButtonSubtext}>1 second</Text>
          </TouchableOpacity>
        )}
      </View>

      {/* Submit Button - Apple style */}
      <TouchableOpacity
        style={[styles.submitButton, (!videoPath || isLoading) && styles.submitButtonDisabled]}
        onPress={handleSubmit}
        disabled={isLoading || !videoPath}
        activeOpacity={0.85}
      >
        {isLoading ? (
          <ActivityIndicator color="#fff" />
        ) : (
          <Text style={styles.submitButtonText}>Continue</Text>
        )}
      </TouchableOpacity>

      {/* Info - Subtle and minimal */}
      <Text style={styles.footerText}>
        Your location will be recorded automatically
      </Text>
    </ScrollView>
  </SafeAreaView>
);

