{"explanation": "將 Data 頁面改成與 Record 頁面一致的優雅簡約設計風格", "code": "import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  FlatList,
  Alert,
  ActivityIndicator,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useFocusEffect } from '@react-navigation/native';
import { getAllEmotionRecords, EmotionRecord } from '@/utils/database';
import { exportAndShareData } from '@/utils/dataExport';

export default function DataScreen() {
  const [records, setRecords] = useState<EmotionRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useFocusEffect(
    React.useCallback(() => {
      loadRecords();
    }, [])
  );

  const loadRecords = async () => {
    setIsLoading(true);
    try {
      console.log('Loading records...');
      const data = await getAllEmotionRecords();
      console.log('Records loaded:', data.length, 'records');
      setRecords(data);
    } catch (error) {
      console.error('Error loading records:', error);
      Alert.alert('Error', 'Failed to load records: ' + (error as Error).message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleExport = async () => {
    try {
      const success = await exportAndShareData();
      if (success) {
        Alert.alert('Success', 'Data exported successfully!');
      }
    } catch (error) {
      console.error('Error exporting data:', error);
      Alert.alert('Error', 'Failed to export data');
    }
  };

  const formatDate = (timestamp: string) => {
    const date = new Date(timestamp);
    return date.toLocaleDateString('en-US', { 
      month: 'short', 
      day: 'numeric',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const getEmotionColor = (score: number): string => {
    if (score <= 5) {
      const ratio = score / 5;
      const red = 220;
      const green = Math.round(180 * ratio);
      return `rgb(${red}, ${green}, 0)`;
    } else {
      const ratio = (score - 5) / 5;
      const red = Math.round(180 * (1 - ratio));
      const green = 180 + Math.round(20 * ratio);
      return `rgb(${red}, ${green}, 0)`;
    }
  };

  if (isLoading) {
    return (
      <View style={styles.loadingContainer}>
        <ActivityIndicator size="large" color="#1a1a1a" />
      </View>
    );
  }

  return (
    <SafeAreaView style={styles.container}>
      {/* Header */}
      <View style={styles.header}>
        <Text style={styles.headerTitle}>Data</Text>
        <Text style={styles.headerSubtitle}>
          {records.length} {records.length === 1 ? 'entry' : 'entries'}
        </Text>
      </View>

      {records.length === 0 ? (
        <View style={styles.emptyContainer}>
          <Text style={styles.emptyText}>No records yet</Text>
          <Text style={styles.emptySubtext}>
            Start tracking your emotions to see your history here
          </Text>
        </View>
      ) : (
        <>
          <FlatList
            data={records}
            keyExtractor={(item) => item.id?.toString() || Math.random().toString()}
            contentContainerStyle={styles.listContent}
            showsVerticalScrollIndicator={false}
            renderItem={({ item }) => (
              <View style={styles.recordCard}>
                <View style={styles.recordHeader}>
                  <Text style={[styles.emotionScore, { color: getEmotionColor(item.emotionScore) }]}>
                    {item.emotionScore}
                  </Text>
                  <Text style={styles.timestamp}>
                    {formatDate(item.timestamp)}
                  </Text>
                </View>

                <View style={styles.recordInfo}>
                  {item.address && (
                    <View style={styles.infoRow}>
                      <Text style={styles.infoLabel}>Location</Text>
                      <Text style={styles.infoValue} numberOfLines={2}>
                        {item.address}
                      </Text>
                    </View>
                  )}

                  {item.latitude && item.longitude && (
                    <View style={styles.infoRow}>
                      <Text style={styles.infoLabel}>Coordinates</Text>
                      <Text style={styles.infoValue}>
                        {item.latitude.toFixed(4)}, {item.longitude.toFixed(4)}
                      </Text>
                    </View>
                  )}

                  {item.videoPath && (
                    <View style={styles.infoRow}>
                      <Text style={styles.infoLabel}>Video</Text>
                      <Text style={styles.infoValue} numberOfLines={1}>
                        Recorded
                      </Text>
                    </View>
                  )}
                </View>
              </View>
            )}
          />

          <TouchableOpacity 
            style={styles.exportButton} 
            onPress={handleExport}
            activeOpacity={0.85}
          >
            <Text style={styles.exportButtonText}>Export Data</Text>
          </TouchableOpacity>
        </>
      )}
    </SafeAreaView>
  );
}

