  if (score === 0) return 'Awfully Bad';
  if (score <= 2) return 'Very Bad';
  if (score <= 4) return 'Bad';
  if (score <= 5) return 'Neutral';
  if (score <= 7) return 'Good';
  if (score <= 9) return 'Very Good';
  return 'Perfectly Good';
};

