{"explanation": "將 Settings 頁面改成與 Record 和 Data 一致的優雅極簡設計風格", "code": "import React, { useState } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  ScrollView,
  Alert,
  Switch,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useFocusEffect } from '@react-navigation/native';
import * as Notifications from 'expo-notifications';
import { getRecordCount, clearAllRecords } from '@/utils/database';
import { scheduleNotifications, cancelAllNotifications } from '@/utils/notifications';

export default function SettingsScreen() {
  const [notificationsEnabled, setNotificationsEnabled] = useState(false);
  const [recordCount, setRecordCount] = useState(0);

  useFocusEffect(
    React.useCallback(() => {
      checkPermissions();
      loadStats();
    }, [])
  );

  const checkPermissions = async () => {
    const { status } = await Notifications.getPermissionsAsync();
    setNotificationsEnabled(status === 'granted');
  };

  const loadStats = async () => {
    console.log('Loading stats...');
    const count = await getRecordCount();
    console.log('Record count:', count);
    setRecordCount(count);
  };

  const handleNotificationToggle = async (value: boolean) => {
    if (value) {
      const { status } = await Notifications.requestPermissionsAsync();
      if (status === 'granted') {
        await scheduleNotifications();
        setNotificationsEnabled(true);
        Alert.alert('Success', 'Daily notifications enabled at 9 AM, 12 PM, and 6 PM');
      } else {
        Alert.alert('Permission Denied', 'Please enable notifications in your device settings');
      }
    } else {
      await cancelAllNotifications();
      setNotificationsEnabled(false);
      Alert.alert('Success', 'Daily notifications disabled');
    }
  };

  const handleTestNotification = async () => {
    try {
      await Notifications.scheduleNotificationAsync({
        content: {
          title: '🎭 Test Notification',
          body: 'If you see this, notifications are working perfectly!',
        },
        trigger: { seconds: 2 },
      });
      Alert.alert('Test Sent', 'You should receive a notification in 2 seconds');
    } catch (error) {
      console.error('Error sending test notification:', error);
      Alert.alert('Error', 'Failed to send test notification');
    }
  };

  const handleClearData = () => {
    Alert.alert(
      'Clear All Data',
      'Are you sure you want to delete all your emotion records? This action cannot be undone.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Clear All',
          style: 'destructive',
          onPress: async () => {
            try {
              await clearAllRecords();
              setRecordCount(0);
              Alert.alert('Success', 'All records have been cleared');
            } catch (error) {
              console.error('Error clearing data:', error);
              Alert.alert('Error', 'Failed to clear data');
            }
          },
        },
      ]
    );
  };

  return (
    <SafeAreaView style={styles.container}>
      <ScrollView 
        contentContainerStyle={styles.scrollContent}
        showsVerticalScrollIndicator={false}
      >
        {/* Header */}
        <View style={styles.header}>
          <Text style={styles.headerTitle}>Settings</Text>
          <Text style={styles.headerSubtitle}>Preferences & Data</Text>
        </View>

        {/* Statistics Section */}
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>Statistics</Text>
          <View style={styles.card}>
            <View style={styles.statRow}>
              <Text style={styles.statLabel}>Total Records</Text>
              <Text style={styles.statValue}>{recordCount}</Text>
            </View>
          </View>
        </View>

        {/* Notifications Section */}
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>Notifications</Text>
          <View style={styles.card}>
            <View style={styles.settingRow}>
              <View style={styles.settingInfo}>
                <Text style={styles.settingLabel}>Daily Reminders</Text>
                <Text style={styles.settingDescription}>
                  9 AM, 12 PM, 6 PM
                </Text>
              </View>
              <Switch
                value={notificationsEnabled}
                onValueChange={handleNotificationToggle}
                trackColor={{ false: '#e5e5e5', true: '#1a1a1a' }}
                thumbColor="#ffffff"
                ios_backgroundColor="#e5e5e5"
              />
            </View>
          </View>

          <TouchableOpacity
            style={styles.secondaryButton}
            onPress={handleTestNotification}
            activeOpacity={0.85}
          >
            <Text style={styles.secondaryButtonText}>Send Test Notification</Text>
          </TouchableOpacity>
        </View>

        {/* Data Management Section */}
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>Data Management</Text>

          <TouchableOpacity
            style={styles.dangerButton}
            onPress={handleClearData}
            activeOpacity={0.85}
          >
            <Text style={styles.dangerButtonText}>Clear All Data</Text>
          </TouchableOpacity>

          <Text style={styles.warningText}>
            This will permanently delete all your emotion records
          </Text>
        </View>

        {/* App Info */}
        <View style={styles.footer}>
          <Text style={styles.footerText}>EmoGo · Version 1.0.0</Text>
          <Text style={styles.footerSubtext}>Emotion Tracking App</Text>
        </View>
      </ScrollView>
    </SafeAreaView>
  );
}

