        <Text style={[styles.headerTitle, { color: colors.text }]}>EmoGo</Text>
        <Text style={[styles.headerSubtitle, { color: colors.textTertiary }]}>
          {recordCount} {recordCount === 1 ? 'entry' : 'entries'}
        </Text>
      </View>

{/* Submit Button - Apple style */}
<TouchableOpacity
