import React, { useState } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  ScrollView,
  Alert,
  Switch,
  Modal,
  Platform,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useFocusEffect } from '@react-navigation/native';
import * as Notifications from 'expo-notifications';
import { getRecordCount } from '@/utils/database';
import { scheduleDailyNotifications } from '@/utils/notifications';
import { useTheme } from '@/contexts/ThemeContext';
import DateTimePicker from '@react-native-community/datetimepicker';

const [showTimeModal, setShowTimeModal] = useState(false);
const [editingTimeIndex, setEditingTimeIndex] = useState<number | null>(null);
const [reminderTimes, setReminderTimes] = useState([
  { hour: 9, minute: 0 },
  { hour: 12, minute: 0 },
  { hour: 18, minute: 0 },
]);

import React from 'react';
import { View, Text, StyleSheet, TouchableOpacity, ScrollView } from 'react-native';

interface TimePickerProps {
  hour: number;
  minute: number;
  onTimeChange: (hour: number, minute: number) => void;
  colors: any;
}

export function TimePicker({ hour, minute, onTimeChange, colors }: TimePickerProps) {
  const hours = Array.from({ length: 24 }, (_, i) => i);
  const minutes = [0, 15, 30, 45];

  return (
    <View style={styles.container}>
      <View style={styles.column}>
        <Text style={[styles.columnLabel, { color: colors.textSecondary }]}>Hour</Text>
        <ScrollView style={styles.scrollView} showsVerticalScrollIndicator={false}>
          {hours.map((h) => (
            <TouchableOpacity
              key={h}
              style={[
                styles.option,
                hour === h && { backgroundColor: colors.primary },
              ]}
              onPress={() => onTimeChange(h, minute)}
            >
              <Text
                style={[
                  styles.optionText,
                  { color: hour === h ? colors.background : colors.text },
                ]}
              >
                {h.toString().padStart(2, '0')}
              </Text>
            </TouchableOpacity>
          ))}
        </ScrollView>
      </View>

      <Text style={[styles.separator, { color: colors.text }]}>:</Text>

      <View style={styles.column}>
        <Text style={[styles.columnLabel, { color: colors.textSecondary }]}>Min</Text>
        <ScrollView style={styles.scrollView} showsVerticalScrollIndicator={false}>
          {minutes.map((m) => (
            <TouchableOpacity
              key={m}
              style={[
                styles.option,
                minute === m && { backgroundColor: colors.primary },
              ]}
              onPress={() => onTimeChange(hour, m)}
            >
              <Text
                style={[
                  styles.optionText,
                  { color: minute === m ? colors.background : colors.text },
                ]}
              >
                {m.toString().padStart(2, '0')}
              </Text>
            </TouchableOpacity>
          ))}
        </ScrollView>
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    height: 200,
  },
  column: {
    width: 80,
  },
  columnLabel: {
    fontSize: 12,
    fontWeight: '300',
    textAlign: 'center',
    marginBottom: 8,
    textTransform: 'uppercase',
    letterSpacing: 0.5,
  },
  scrollView: {
    height: 180,
  },
  option: {
    paddingVertical: 12,
    paddingHorizontal: 16,
    borderRadius: 8,
    marginVertical: 2,
    alignItems: 'center',
  },
  optionText: {
    fontSize: 18,
    fontWeight: '400',
  },
  separator: {
    fontSize: 24,
    fontWeight: '200',
    marginHorizontal: 12,
  },
});

const formatTime = (hour: number, minute: number) => {
  return `${hour.toString().padStart(2, '0')}:${minute.toString().padStart(2, '0')}`;
};

const handleTimeChange = (index: number, hour: number, minute: number) => {
  const newTimes = [...reminderTimes];
  newTimes[index] = { hour, minute };
  setReminderTimes(newTimes);
};

const handleSaveTimes = () => {
  setShowTimeModal(false);
  setEditingTimeIndex(null);
  Alert.alert('Success', 'Reminder times updated. Please toggle notifications to apply changes.');
};

{/* Time Picker Modal */}
<Modal
  visible={showTimeModal}
  transparent
  animationType="fade"
  onRequestClose={() => setShowTimeModal(false)}
>
  <View style={dynamicStyles.modalContainer}>
    <View style={dynamicStyles.modalContent}>
      <Text style={dynamicStyles.modalTitle}>Set Reminder Times</Text>

      {['Morning', 'Afternoon', 'Evening'].map((label, index) => (
        <View key={index} style={dynamicStyles.timeInputContainer}>
          <Text style={dynamicStyles.timeLabel}>{label}</Text>
          <TouchableOpacity
            style={dynamicStyles.timeDisplay}
            onPress={() => setEditingTimeIndex(index)}
          >
            <Text style={[dynamicStyles.timeDisplayText, { color: colors.text }]}>
              {formatTime(reminderTimes[index].hour, reminderTimes[index].minute)}
            </Text>
          </TouchableOpacity>

          {editingTimeIndex === index && (
            <TimePicker
              hour={reminderTimes[index].hour}
              minute={reminderTimes[index].minute}
              onTimeChange={(hour, minute) => handleTimeChange(index, hour, minute)}
              colors={colors}
            />
          )}
        </View>
      ))}

      <View style={dynamicStyles.modalButtons}>
        <TouchableOpacity
          style={[dynamicStyles.modalButton, dynamicStyles.modalButtonSecondary]}
          onPress={() => {
            setShowTimeModal(false);
            setEditingTimeIndex(null);
          }}
        >
          <Text style={dynamicStyles.modalButtonTextSecondary}>Cancel</Text>
        </TouchableOpacity>
        <TouchableOpacity
          style={[dynamicStyles.modalButton, dynamicStyles.modalButtonPrimary]}
          onPress={handleSaveTimes}
        >
          <Text style={dynamicStyles.modalButtonTextPrimary}>Save</Text>
        </TouchableOpacity>
      </View>
    </View>
  </View>
</Modal>

