import * as Location from 'expo-location';

export interface WeatherData {
  temperature: number;
  condition: string;
  description: string;
  humidity: number;
  icon: string;
}

export const getCurrentWeather = async (
  latitude: number,
  longitude: number
): Promise<WeatherData | null> => {
  try {
    // 使用 OpenWeatherMap API (需要註冊免費 API key)
    const API_KEY = 'YOUR_API_KEY'; // 可以稍後替換
    const url = `https://api.openweathermap.org/data/2.5/weather?lat=${latitude}&lon=${longitude}&units=metric&appid=${API_KEY}`;

    const response = await fetch(url);

    if (!response.ok) {
      console.error('Weather API error:', response.status);
      return null;
    }

    const data = await response.json();

    return {
      temperature: Math.round(data.main.temp),
      condition: data.weather[0].main,
      description: data.weather[0].description,
      humidity: data.main.humidity,
      icon: getWeatherEmoji(data.weather[0].main),
    };
  } catch (error) {
    console.error('Error fetching weather:', error);
    return null;
  }
};

// 將天氣狀況轉換為 emoji
const getWeatherEmoji = (condition: string): string => {
  const weatherMap: { [key: string]: string } = {
    'Clear': '☀️',
    'Clouds': '☁️',
    'Rain': '🌧️',
    'Drizzle': '🌦️',
    'Thunderstorm': '⛈️',
    'Snow': '❄️',
    'Mist': '🌫️',
    'Fog': '🌫️',
    'Haze': '🌫️',
  };

  return weatherMap[condition] || '🌤️';
};

// 備用方案：使用免費的 wttr.in API（無需 API key）
export const getWeatherSimple = async (
  latitude: number,
  longitude: number
): Promise<WeatherData | null> => {
  try {
    const url = `https://wttr.in/${latitude},${longitude}?format=j1`;

    const response = await fetch(url);

