const db = SQLite.openDatabaseSync('emogo.db');

export interface EmotionRecord {
  id?: number;
  timestamp: string;
  emotionScore: number;
  videoPath: string;
  latitude: number | null;
  longitude: number | null;
  address: string | null;
  temperature: number | null;
  weatherCondition: string | null;
  weatherIcon: string | null;
}

export const initDatabase = async () => {
  try {
    // 創建基礎表
    await db.execAsync(`
      CREATE TABLE IF NOT EXISTS emotion_records (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp TEXT NOT NULL,
        emotionScore INTEGER NOT NULL,
        videoPath TEXT NOT NULL,
        latitude REAL,
        longitude REAL,
        address TEXT
      );
    `);

    // 遷移：添加天氣欄位（如果不存在）
    const tableInfo = await db.getAllAsync(`PRAGMA table_info(emotion_records)`);
    const columns = tableInfo.map((col: any) => col.name);

    if (!columns.includes('temperature')) {
      await db.execAsync(`ALTER TABLE emotion_records ADD COLUMN temperature INTEGER;`);
      console.log('Added temperature column');
    }

    if (!columns.includes('weatherCondition')) {
      await db.execAsync(`ALTER TABLE emotion_records ADD COLUMN weatherCondition TEXT;`);
      console.log('Added weatherCondition column');
    }

    if (!columns.includes('weatherIcon')) {
      await db.execAsync(`ALTER TABLE emotion_records ADD COLUMN weatherIcon TEXT;`);
      console.log('Added weatherIcon column');
    }

    console.log('Database initialized successfully');
  } catch (error) {
    console.error('Error initializing database:', error);
    throw error;
  }
};

export const insertEmotionRecord = async (record: Omit<EmotionRecord, 'id'>) => {
  try {
    const result = await db.runAsync(
      `INSERT INTO emotion_records 
       (timestamp, emotionScore, videoPath, latitude, longitude, address, temperature, weatherCondition, weatherIcon) 
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      record.timestamp,
      record.emotionScore,
      record.videoPath,
      record.latitude,
      record.longitude,
      record.address,
      record.temperature,
      record.weatherCondition,
      record.weatherIcon
    );
    console.log('Record inserted with ID:', result.lastInsertRowId);
    return result.lastInsertRowId;
  } catch (error) {
    console.error('Error inserting record:', error);
    throw error;
  }
};

export const getAllEmotionRecords = async (): Promise<EmotionRecord[]> => {
  try {
    const records = await db.getAllAsync<EmotionRecord>(
      'SELECT * FROM emotion_records ORDER BY timestamp DESC'
    );
    return records;
  } catch (error) {
    console.error('Error getting all records:', error);
    throw error;
  }
};

export const getRecordCount = async (): Promise<number> => {
  try {
    const result = await db.getFirstAsync<{ count: number }>(
      'SELECT COUNT(*) as count FROM emotion_records'
    );
    return result?.count || 0;
  } catch (error) {
    console.error('Error getting record count:', error);
    return 0;
  }
};

export const clearAllRecords = async (): Promise<void> => {
  try {
    await db.runAsync('DELETE FROM emotion_records');
    console.log('All records cleared successfully');
  } catch (error) {
    console.error('Error clearing all records:', error);
    throw error;
  }
};
