const handleTestNotification = async () => {
  try {
    // 立即通知測試
    await Notifications.scheduleNotificationAsync({
      content: {
        title: '🎭 Immediate Test',
        body: 'This should appear now!',
      },
      trigger: null,
    });

    // 1分鐘後的通知測試
    const now = new Date();
    const oneMinuteLater = new Date(now.getTime() + 60 * 1000);

    await Notifications.scheduleNotificationAsync({
      content: {
        title: '⏰ 1-Minute Test',
        body: 'This notification was scheduled 1 minute ago!',
      },
      trigger: {
        type: Notifications.SchedulableTriggerInputTypes.DATE,
        date: oneMinuteLater,
      },
    });

    Alert.alert(
      'Tests Scheduled', 
      `1. Immediate notification sent\n2. Another in 1 minute at ${oneMinuteLater.toLocaleTimeString()}`
    );
  } catch (error) {
    console.error('Error sending test notification:', error);
    Alert.alert('Error', 'Failed to send test notification');
  }
};

const scheduleCustomNotifications = async (times: { hour: number; minute: number }[]) => {
  try {
    // 取消所有現有通知
    await Notifications.cancelAllScheduledNotificationsAsync();

    // 排程自定義時間的通知
    for (const time of times) {
      // 計算下一個該時間點
      const now = new Date();
      const scheduledDate = new Date();
      scheduledDate.setHours(time.hour, time.minute, 0, 0);

      // 如果該時間已過，設為明天
      if (scheduledDate <= now) {
        scheduledDate.setDate(scheduledDate.getDate() + 1);
      }

      await Notifications.scheduleNotificationAsync({
        content: {
          title: '🎭 Time to record your emotions',
          body: 'Take a moment to check in with yourself',
          sound: true,
        },
        trigger: {
          type: Notifications.SchedulableTriggerInputTypes.DAILY,
          hour: time.hour,
          minute: time.minute,
        },
      });

      console.log(`Scheduled daily notification for ${formatTime(time.hour, time.minute)} (next at ${scheduledDate.toLocaleString()})`);
    }

    // 驗證通知已排程
    const scheduled = await Notifications.getAllScheduledNotificationsAsync();
    console.log(`Total scheduled notifications: ${scheduled.length}`);
  } catch (error) {
    console.error('Error scheduling custom notifications:', error);
    Alert.alert('Error', `Failed to schedule notifications: ${error}`);
  }
};

